{"file_path":"F:\programms\github\tzyoutube\tests\test_frontend_js_contract.py","content":""""JS-API contract guard (bug A): every URL literal that static/*.js sends
via fetch / XMLHttpRequest / tzApi, and every /api|//auth URL in templates
(form actions, links), must match a route + method from app.openapi()
(path parameters accounted for).

Also guards SSR page links/navigation (href="...", window.location.href)
against the pages router, so a typo'd page URL is caught too.

Red on the buggy code: app.js logout POST /api/auth/logout and
auth.js POST /api/auth/{register,login} do not exist in openapi()
(real auth routes live under /auth, not /api/auth).
"""

import re
from pathlib import Path

from app import pages as pages_api
from app.main import create_app

ROOT = Path(__file__).resolve().parent.parent
STATIC = ROOT / "src" / "app" / "static"
TEMPLATES = ROOT / "src" / "app" / "templates"


def _api_routes() -> list[tuple[str, str]]:
    """(METHOD, path_template) for every /api and /auth route in openapi()."""
    spec = create_app().openapi()
    out = []
    for path, ops in spec["paths"].items():
        if path.startswith(("/api", "/auth")):
            for method in ops:
                out.append((method.upper(), path))
    return out


def _page_routes() -> list[tuple[str, str]]:
    """(METHOD, path_template) for SSR page routes (include_in_schema=False)."""
    out = []
    for r in pages_api.router.routes:
        methods = getattr(r, "methods", None) or {"GET"}
        for m in methods:
            out.append((m.upper(), r.path))
    return out


def _route_regex(template: str) -> re.Pattern:
    """'/api/videos/{video_id}/status' -> ^/api/videos/[^/]+/status$"""
    pattern = re.sub(r"\{[^}]+\}", "[^/]+", template)
    pattern = re.sub(r"\{\{[^}]+\}\}", "[^/]+", pattern)  # jinja {{ var }}
    return re.compile("^" + pattern + "$")


def _read_path_expr(source: str, i: int) -> tuple[str, int]:
    """Scan a JS path expression starting at index i: string literals joined by
    '+'. Each non-literal operand becomes a [^/]+ wildcard segment.
    Returns (regex_pattern, end_index)."""
    parts: list[str] = []
    n = len(source)
    while i < n:
        ch = source[i]
        if ch in " \t\r\n":
            i += 1
            continue
        if ch in "\"'":
            q = ch
            i += 1
            buf: list[str] = []
            while i < n and source[i] != q:
                if source[i] == "\\" and i + 1 < n:
                    buf.append(source[i + 1])
                    i += 2
                else:
                    buf.append(source[i])
                    i += 1
            i += 1  # closing quote
            parts.append(re.escape("".join(buf)))
        else:
            break
        # after a literal: look for '+' to continue the concatenation
        j = i
        while j < n and source[j] in " \t\r\n":
            j += 1
        if j < n and source[j] == "+":
            i = j + 1
            # consume the operand expression -> one wildcard segment
            while i < n and source[i] in " \t\r\n":
                i += 1
            depth = 0
            while i < n:
                c = source[i]
                if c in "([{":
                    depth += 1
                elif c in ")]}":
                    if depth == 0:
                        break
                    depth -= 1
                elif c in "+," and depth == 0:
                    break
                i += 1
            parts.append("[^/]+")
            continue
        break
    return "".join(parts), i


_TZ_SHORT = {"post": "POST", "del": "DELETE", "patch": "PATCH", "get": "GET"}


def _js_api_calls(source: str) -> list[tuple[str, str, str]]:
    """Yield (method, path_regex, snippet) for API/page calls in a JS file."""
    calls: list[tuple[str, str, str]] = []
    # xhr.open("METHOD", "PATH" ...)
    for m in re.finditer(r"\.open\s*\(\s*[\"']([A-Za-z]+)[\"']\s*,\s*", source):
        method = m.group(1).upper()
        pat, _ = _read_path_expr(source, m.end())
        if pat:
            calls.append((method, pat, source[m.start(): m.start() + 90]))
    # tzApi.post/del/patch/get("PATH") | tzApi("PATH", {method}) | fetch("PATH")
    for m in re.finditer(r"(?:tzApi(?:\.(post|del|patch|get))?|fetch)\s*\(\s*", source):
        tail = source[m.start(): m.start() + 140]
        if m.group(1):
            method = _TZ_SHORT[m.group(1)]
        else:
            mm = re.search(r"method\s*:\s*[\"']([A-Za-z]+)[\"']", tail)
            method = mm.group(1).upper() if mm else "GET"
        pat, _ = _read_path_expr(source, m.end())
        if pat:
            calls.append((method, pat, tail.split("\n")[0]))
    # window.location.href = "PATH" / window.location.reload() etc.
    for m in re.finditer(r"location\.href\s*=\s*", source):
        pat, _ = _read_path_expr(source, m.end())
        if pat:
            calls.append(("GET", pat, source[m.start(): m.start() + 90].split("\n")[0]))
    return calls


def _template_urls(source: str) -> list[tuple[str, str, str]]:
    """Yield (method, path_regex, snippet) for href=/action=/src= literals."""
    out: list[tuple[str, str, str]] = []
    for m in re.finditer(r"\b(href|action|src)\s*=\s*\"([^\"]*)\"", source):
        attr, raw = m.group(1), m.group(2)
        if not raw.startswith("/") or raw.startswith(("/static/", "/media/")):
            continue
        # strip query/fragment for matching
        path = raw.split("?", 1)[0].split("#", 1)[0]
        pat = re.escape(path)
        pat = re.sub(r"%7B[^}]*%7D|\{\{[^}]+\}\}", "[^/]+", pat)  # {{ var }} / encoded
        # method: form action uses the form's method attr (default GET)
        method = "GET"
        if attr == "action":
            seg = source[m.start(): m.start() + 300]
            mm = re.search(r"method\s*=\s*\"([A-Za-z]+)\"", seg)
            if mm:
                method = mm.group(1).upper()
        out.append((method, "^" + pat + "$", raw))
    return out


def _strip_query_fragment(pat: str) -> str:
    return pat


def test_js_and_template_urls_match_openapi_routes() -> None:
    api_routes = _api_routes()
    api_patterns = [(m, _route_regex(p), p) for m, p in api_routes]
    page_routes = _page_routes()
    page_patterns = [(m, _route_regex(p), p) for m, p in page_routes]

    failures: list[str] = []

    for f in sorted(STATIC.glob("*.js")):
        src = f.read_text(encoding="utf-8")
        for method, pat, snippet in _js_api_calls(src):
            regex = re.compile(pat + "$")
            haystack = api_patterns if pat.startswith("/api") or pat.startswith("/auth") else page_patterns
            if not any(m == method and rx.match(regex.pattern[:-1]) for m, rx, _ in haystack):
                # also try matching without method restriction for page GET
                if not any(rx.match(pat) for _, rx, _ in haystack):
                    failures.append(f"{f.name}: {method} {pat!r}  <- {snippet!r}")

    for f in sorted(TEMPLATES.glob("*.html")):
        src = f.read_text(encoding="utf-8")
        for method, pat, raw in _template_urls(src):
            rx = re.compile(pat)
            if pat.startswith("/api") or pat.startswith("/auth"):
                ok = any(m == method and rx.match(p) for m, p in api_routes)
            else:
                ok = any(rx.match(p) for _, p in page_routes)
            if not ok:
                failures.append(f"{f.name}: {method} {raw!r}")

    assert not failures, "JS/template URL literals with no matching route:\n" + "\n".join(failures)


def test_js_api_methods_exist_for_paths() -> None:
    """Each JS API call's method must be allowed on a matching route."""
    api_routes = _api_routes()
    failures: list[str] = []
    for f in sorted(STATIC.glob("*.js")):
        src = f.read_text(encoding="utf-8")
        for method, pat, snippet in _js_api_calls(src):
            if not (pat.startswith("/api") or pat.startswith("/auth")):
                continue
            regex = re.compile(pat + "$")
            ok = any(m == method and regex.match(p) for m, p in api_routes)
            if not ok:
                failures.append(f"{f.name}: {method} {pat!r} no such API route ({snippet!r})")
    assert not failures, "\n".join(failures)
"}

